"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["61825"],{6512(a){a.exports=JSON.parse('{"id":"V4-185","slug":"financial-stability-board","term":"Financial Stability Board (FSB)","also_known_as":[],"difficulty":"Advanced","definition":"The Financial Stability Board (FSB) is an international body that monitors and makes recommendations about the global financial system, coordinating the work of national financial authorities and international standard-setting bodies.","explanation":["The FSB was established in 2009, after the 2008 financial crisis, by the G20 group of major economies. It replaced the Financial Stability Forum, created in 1999. It is hosted by the Bank for International Settlements in Basel.","Its members include finance ministries, central banks and financial regulators from major economies, as well as international organisations such as the International Monetary Fund, World Bank and international standard-setting bodies.","The FSB\u2019s work has included identifying global systemically important banks and insurers, which face extra requirements; developing standards for resolving failing banks without taxpayer bailouts; reforming over-the-counter derivatives markets; and monitoring risks from non-bank financial institutions, crypto assets and climate change.","For example, the FSB publishes an annual list of global systemically important banks, which must hold additional capital and meet stricter requirements.","The FSB\u2019s recommendations are not legally binding. Members commit to implementing agreed standards through their national laws and regulations. The FSB also created the Task Force on Climate-related Financial Disclosures."],"note":"","total":1725,"prev":{"slug":"financial-security","term":"Financial Security"},"next":{"slug":"financial-statement","term":"Financial Statement"}}')}}]);